using Xunit;

public class U03_AlarmsTest
{
    [Fact]
    public void Test_LOW_VTI_Alarm_Active_Above_Threshold()
    {
        // Arrange
        var threshold = 10;
        var vti = 12;

        // Act
        var alarm = new Alarm(threshold);
        alarm.ComputeVTI(vti);

        // Assert
        Assert.True(alarm.IsLowVTIAlarmActive);
    }

    [Fact]
    public void Test_LOW_VTI_Alarm_Inactive_Below_Threshold()
    {
        // Arrange
        var threshold = 10;
        var vti = 8;

        // Act
        var alarm = new Alarm(threshold);
        alarm.ComputeVTI(vti);

        // Assert
        Assert.False(alarm.IsLowVTIAlarmActive);
    }

    [Fact]
    public void Test_HIGH_VTI_Alarm_Active_Above_Threshold()
    {
        // Arrange
        var threshold = 15;
        var vti = 18;

        // Act
        var alarm = new Alarm(threshold);
        alarm.ComputeVTI(vti);

        // Assert
        Assert.True(alarm.IsHighVTIAlarmActive);
    }

    [Fact]
    public void Test_HIGH_VTI_Alarm_Inactive_Below_Threshold()
    {
        // Arrange
        var threshold = 15;
        var vti = 12;

        // Act
        var alarm = new Alarm(threshold);
        alarm.ComputeVTI(vti);

        // Assert
        Assert.False(alarm.IsHighVTIAlarmActive);
    }

    [Fact]
    public void Test_LOW_VTE_Alarm_Active_Above_Threshold()
    {
        // Arrange
        var threshold = 5;
        var vte = 7;

        // Act
        var alarm = new Alarm(threshold);
        alarm.ComputeVTE(vte);

        // Assert
        Assert.True(alarm.IsLowVTEAlarmActive);
    }

    [Fact]
    public void Test_LOW_VTE_Alarm_Inactive_Below_Threshold()
    {
        // Arrange
        var threshold = 5;
        var vte = 3;

        // Act
        var alarm = new Alarm(threshold);
        alarm.ComputeVTE(vte);

        // Assert
        Assert.False(alarm.IsLowVTEAlarmActive);
    }
}
